CREATE TABLE IF NOT EXISTS richo_continuity_exercises_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),service_id text NOT NULL,exercise_type text NOT NULL,result jsonb NOT NULL,passed boolean NOT NULL,performed_at timestamptz NOT NULL DEFAULT now(),evidence_digest text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_failover_plans_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),service_id text NOT NULL,primary_provider text,primary_region text,provider_fallback jsonb,region_fallback jsonb,ready boolean NOT NULL DEFAULT false,verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_degraded_modes_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),service_id text NOT NULL,name text NOT NULL,capability_pct numeric(6,2) NOT NULL,requirements jsonb NOT NULL DEFAULT '[]'::jsonb,runbook jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_continuity_confidence_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),service_id text NOT NULL,score integer NOT NULL,status text NOT NULL,metrics jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
